create or replace function public.gateway_json_contains_forbidden_payment_data(p_value jsonb) returns boolean language plpgsql immutable as $$ declare k text; v jsonb; begin if p_value is null then return false; end if; if jsonb_typeof(p_value)='object' then for k,v in select key,value from jsonb_each(p_value) loop if lower(regexp_replace(k,'[^a-z0-9]','','g')) in ('pan','cardnumber','cardnum','cvv','cvc','securitycode','securitynumber','expiration','expiry','expirymonth','expiryyear','trackdata','magstripe') then return true; end if; if public.gateway_json_contains_forbidden_payment_data(v) then return true; end if; end loop; elsif jsonb_typeof(p_value)='array' then for v in select value from jsonb_array_elements(p_value) loop if public.gateway_json_contains_forbidden_payment_data(v) then return true; end if; end loop; end if; return false; end $$;
create or replace function public.guard_gateway_transaction_sensitive_payload() returns trigger language plpgsql security definer set search_path=public as $$ begin if public.gateway_json_contains_forbidden_payment_data(coalesce(new.metadata,'{}'::jsonb)) or public.gateway_json_contains_forbidden_payment_data(coalesce(new.customer,'{}'::jsonb)) then raise exception 'raw_payment_card_data_forbidden'; end if; return new; end $$;
drop trigger if exists trg_gateway_transaction_sensitive_payload on public.gateway_transactions;
create trigger trg_gateway_transaction_sensitive_payload before insert or update of metadata,customer on public.gateway_transactions for each row execute function public.guard_gateway_transaction_sensitive_payload();
